contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        require(target != address(0));
        require(target != address(c));
        require(value > 0);
        require(address(this).balance >= value);
        require(address(c).balance >= value);

        address owner = c.owner();
        require(owner == address(this));

        uint targetBefore = target.balance;
        uint contractBefore = address(c).balance;

        bool reverted;
        try c.sendMoney{value: 0}(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted &&
            address(c).balance == contractBefore - value &&
            target.balance == targetBefore + value
        );
    }

    receive() external payable {}
}

